package dev.kosmx.playerAnim.minecraftApi;import java.util.*;public class PlayerAnimationAccess {public static int accesses;public static Data data=new Data();public static Data getPlayerAssociatedData(Object p){accesses++;return data;}public static class Data {public final Map<Object,Layer>layers=new HashMap<>();public Object get(Object id){return layers.get(id);}}public static class Layer {public Object animation=new Object();public List<Object> modifiers=new ArrayList<>();public void setAnimation(Object a){animation=a;}public void removeModifier(int i){modifiers.remove(i);}}}
